// Test Suite for Lab Incharge, Chemist, and Admin functionalities

// Test Case for Lab Incharge to perform offline and online lab tests and update reports
class TestLabIncharge {
    [Test]
    public void PerformLabTestsAndUpdateReports() {
        // Arrange
        var labIncharge = new LabIncharge();
        var report = new Report();

        // Act
        labIncharge.PerformLabTests();
        labIncharge.UpdateReport(report);

        // Assert
        Assert.AreEqual(true, report.IsUpdated);
    }

    [Test]
    public void SetFlagInPrescription() {
        // Arrange
        var labIncharge = new LabIncharge();
        var prescription = new Prescription();

        // Act
        labIncharge.SetFlagInPrescription();

        // Assert
        Assert.AreEqual(true, prescription.IsFlagged);
    }
}

// Test Case for Chemist to deliver medicine offline and set flag in prescription
class TestChemist {
    [Test]
    public void DeliverMedicine() {
        // Arrange
        var chemist = new Chemist();
        var medicine = new Medicine();

        // Act
        chemist.DeliverMedicine(medicine);

        // Assert
        Assert.AreEqual(true, medicine.IsDelivered);
    }

    [Test]
    public void SetFlagInPrescription() {
        // Arrange
        var chemist = new Chemist();
        var prescription = new Prescription();

        // Act
        chemist.SetFlagInPrescription();

        // Assert
        Assert.AreEqual(true, prescription.IsFlagged);
    }
}

// Test Case for Admin to view invoice and reports
class TestAdmin {
    [Test]
    public void ViewInvoiceAndReports() {
        // Arrange
        var admin = new Admin();
        var invoice = new Invoice();
        var report = new Report();

        // Act
        admin.ViewInvoiceAndReports(invoice, report);

        // Assert
        Assert.AreEqual(true, invoice.IsViewed);
        Assert.AreEqual(true, report.IsViewed);
    }
}
